package revisitledger;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class CliTest {
 @TempDir Path temp;
 record Result(int exit,String out,String err){}
 Result run(String... args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=Cli.run(args,new PrintStream(out),new PrintStream(err));return new Result(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
 Path corpus()throws IOException{Path root=Files.createDirectory(temp.resolve("corpus"));for(String name:List.of("A.warc","B.warc","C.warc"))Files.copy(Path.of("tests/fixtures/derived/whole-file",name),root.resolve(name));return root;}
 Path list(String name,String contents)throws IOException{return Files.writeString(temp.resolve(name),contents);}
 String[] audit(Path root,Path files,Path report,String...extra){var a=new ArrayList<>(List.of("audit","--root",root.toString(),"--files",files.toString(),"--json",report.toString(),"--scratch",temp.toString()));a.addAll(List.of(extra));return a.toArray(String[]::new);}
 @Test void helpAndInvalidArguments(){assertEquals(0,run("--help").exit);assertEquals(0,run("--version").exit);for(var args:List.of(new String[]{},new String[]{"unknown"},new String[]{"audit"},new String[]{"audit","--root","x","--root","y"},new String[]{"audit","--max-records","-1"}))assertEquals(2,run(args).exit);}
 @Test void exitCodes012AndCompleteness()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n"),good=temp.resolve("good.json");assertEquals(0,run(audit(root,files,good)).exit);assertTrue(Files.readString(good).contains("\"complete\":true"));Path missing=list("missing.txt","A.warc\n");assertEquals(1,run(audit(root,missing,temp.resolve("blocked.json"))).exit);Files.writeString(root.resolve("bad.warc"),"broken");assertEquals(2,run(audit(root,list("bad.txt","bad.warc\n"),temp.resolve("bad.json"))).exit);assertFalse(Files.readString(temp.resolve("bad.json")).contains("\"complete\":true"));}
 @Test void deterministicOrderAndUnchangedArchives()throws Exception{Path root=corpus();Map<String,byte[]>before=new TreeMap<>();for(String s:List.of("A.warc","B.warc","C.warc"))before.put(s,Files.readAllBytes(root.resolve(s)));Path one=temp.resolve("one.json"),two=temp.resolve("two.json");assertEquals(0,run(audit(root,list("one.txt","A.warc\nB.warc\nC.warc\n"),one)).exit);assertEquals(0,run(audit(root,list("two.txt","C.warc\nA.warc\nB.warc\n"),two)).exit);assertArrayEquals(Files.readAllBytes(one),Files.readAllBytes(two));for(var e:before.entrySet())assertArrayEquals(e.getValue(),Files.readAllBytes(root.resolve(e.getKey())));}
 @Test void noInputOverwriteViaHardlink()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n"),alias=temp.resolve("alias.json");Files.createLink(alias,root.resolve("A.warc"));byte[]before=Files.readAllBytes(alias);assertEquals(2,run(audit(root,files,alias,"--overwrite")).exit);assertArrayEquals(before,Files.readAllBytes(alias));assertEquals(2,run(audit(root,files,files,"--overwrite")).exit);}
 @Test void noClobberAndExplicitOverwrite()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n"),report=list("report.json","sentinel");assertEquals(2,run(audit(root,files,report)).exit);assertEquals("sentinel",Files.readString(report));assertEquals(0,run(audit(root,files,report,"--overwrite")).exit);assertTrue(Files.readString(report).startsWith("{"));}
 @Test void symlinkDestinationsAndTraversalRejected()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n");Files.createSymbolicLink(temp.resolve("linked"),root);assertEquals(2,run(audit(root,files,temp.resolve("linked/report.json"))).exit);assertEquals(2,run(audit(root,list("unsafe.txt","../corpus/A.warc\n"),temp.resolve("out.json"))).exit);assertEquals(2,run(audit(root,files,temp.resolve("corpus/../out.json"))).exit);}
 @Test void noAbsolutePathsOrPayloadExcerpts()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n"),report=temp.resolve("out.json");Result r=run(audit(root,files,report));assertEquals(0,r.exit);String all=Files.readString(report)+r.out+r.err;assertFalse(all.contains(temp.toString()));assertFalse(all.contains("some\\ntext"));Result error=run(audit(root,files,temp.resolve("missing/out.json")));assertEquals(2,error.exit);assertFalse(error.err.contains(temp.toString()));}
 @Test void planIncludesWholeAddedFilesAndExplain()throws Exception{Path root=corpus(),files=list("all.txt","C.warc\nA.warc\nB.warc\n"),seeds=list("seeds.txt","A.warc\n"),report=temp.resolve("plan.json");var args=new ArrayList<>(List.of(audit(root,files,report)));args.set(0,"plan");args.addAll(List.of("--seeds",seeds.toString()));assertEquals(0,run(args.toArray(String[]::new)).exit);Result explanation=run("explain","--report",report.toString(),"--record","A.warc#1");assertEquals(0,explanation.exit);assertTrue(explanation.out.contains("A.warc"));assertFalse(explanation.out.contains(temp.toString()));assertEquals(2,run("explain","--report",report.toString(),"--record","../A.warc#1").exit);}
 @Test void limitsReturnIncompleteAndCleanScratch()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n"),report=temp.resolve("limit.json");assertEquals(2,run(audit(root,files,report,"--max-records","1")).exit);try(var stream=Files.list(temp)){assertFalse(stream.anyMatch(p->p.getFileName().toString().startsWith("revisitledger-")));}assertEquals(2,run(audit(root,files,temp.resolve("quota.json"),"--max-scratch-bytes","1")).exit);assertFalse(Files.exists(temp.resolve("quota.json")));}
 @Test void listUtf8DuplicatesAndUnexpectedFlagsRejected()throws Exception{Path root=corpus(),files=list("all.txt","A.warc\nA.warc\n");assertEquals(2,run(audit(root,files,temp.resolve("out.json"))).exit);Files.write(files,new byte[]{(byte)0xc3,(byte)0x28});assertEquals(2,run(audit(root,files,temp.resolve("out.json"))).exit);assertEquals(2,run(audit(root,list("ok.txt","A.warc\n"),temp.resolve("out.json"),"--seeds",files.toString())).exit);}
 @Test void everySuppliedChoiceMustBeEnumeratedEvenOutsideSelectedSubset()throws Exception{
  Path root=corpus(),files=list("all.txt","A.warc\nB.warc\nC.warc\n"),baseline=temp.resolve("baseline.json");assertEquals(0,run(audit(root,files,baseline)).exit);
  var matcher=java.util.regex.Pattern.compile("\"corpusFingerprint\":\"([0-9a-f]{64})\"").matcher(Files.readString(baseline));assertTrue(matcher.find());String fingerprint=matcher.group(1);
  Path choices=list("choices.json","{\"version\":1,\"corpusFingerprint\":\""+fingerprint+"\",\"bindings\":[{\"consumer\":{\"path\":\"A.warc\",\"ordinal\":1},\"provider\":{\"path\":\"C.warc\",\"ordinal\":1}}]}");
  var args=new ArrayList<>(List.of(audit(root,files,temp.resolve("invalid-choice.json"))));args.set(0,"plan");args.addAll(List.of("--seeds",list("seeds.txt","C.warc\n").toString(),"--choices",choices.toString()));
  assertEquals(2,run(args.toArray(String[]::new)).exit);assertFalse(Files.exists(temp.resolve("invalid-choice.json")));
 }
 @Test void explicitEnumeratedChoiceResolvesAmbiguityAndStaleFingerprintFails()throws Exception{
  Path root=corpus();Files.copy(root.resolve("B.warc"),root.resolve("D.warc"));Path files=list("all.txt","A.warc\nB.warc\nC.warc\nD.warc\n"),baseline=temp.resolve("ambiguous.json");assertEquals(1,run(audit(root,files,baseline)).exit);
  var matcher=java.util.regex.Pattern.compile("\"corpusFingerprint\":\"([0-9a-f]{64})\"").matcher(Files.readString(baseline));assertTrue(matcher.find());String fingerprint=matcher.group(1);
  String choice="{\"version\":1,\"corpusFingerprint\":\""+fingerprint+"\",\"bindings\":[{\"consumer\":{\"path\":\"A.warc\",\"ordinal\":1},\"provider\":{\"path\":\"D.warc\",\"ordinal\":1}}]}";
  Path choices=list("choices.json",choice),result=temp.resolve("chosen.json");var args=new ArrayList<>(List.of(audit(root,files,result)));args.set(0,"plan");args.addAll(List.of("--seeds",list("seed.txt","A.warc\n").toString(),"--choices",choices.toString()));
  assertEquals(0,run(args.toArray(String[]::new)).exit);assertTrue(Files.readString(result).contains("\"includedFiles\":[\"A.warc\",\"C.warc\",\"D.warc\"]"));
  Files.writeString(choices,choice.replace(fingerprint,"0".repeat(64)));args.add("--overwrite");byte[]before=Files.readAllBytes(result);assertEquals(2,run(args.toArray(String[]::new)).exit);assertArrayEquals(before,Files.readAllBytes(result));
 }
}
